mapper.update:
UPDATE dcr05_doc_type
   SET dcr05_title             = #{req.title},
       dcr05_content           = #{req.content},
       dcr05_note              = #{req.note},
       dcr05_doc_form_class_cd = #{req.docFormClassCode}
 WHERE dcr05_doc_type_id = #{docTypeId}
   AND dcr05_company_id  = #{companyId}

mapper.delete:
DELETE FROM dcr05_doc_type
 WHERE dcr05_company_id = #{companyId}
   AND dcr05_doc_type_id IN
#{id}

mapper.select:
SELECT COUNT(*)
  FROM dcr05_doc_type
 WHERE dcr05_company_id        = #{companyId}
   AND dcr05_doc_form_class_cd = #{docFormClassCode}
